typedef float vm_num_t;

class vm_stack
{
public:
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

void error(const char* message);

#define TARGET_MKS
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( "script stack overflow" )
#define SLF_DONE \
  return true

class slf_TARGET_PC_t : public script_library_class::function
{
  public:
    virtual bool operator()(vm_stack& stack,entry_t entry)
    {
#if defined (TARGET_PC)
      vm_num_t result = true;
#else
      vm_num_t result = false;
#endif
      SLF_RETURN;
      SLF_DONE;
    }
};
